import torch
from torch import cos, sin

def get_spherical_harmonic(m,l):
  fname = f"Yl{l}_m{m}".replace("-","_minus_")
  return globals()[fname]

def spherical_harmonic(m, l, phi, theta):
  Ylm = get_spherical_harmonic(m,l)
  return Ylm(theta, phi)



